string toLowerCamel(const vector<string>& words) {
    string result;
    for (size_t j = 0; j < words.size(); j++) {
        const string& w = words[j];
        for (size_t i = 0; i < w.size(); i++) {
            if (i == 0) {
                if (j == 0) {
