        // Remove newline
        int len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
            line[--len] = '\0';
        }

        if (strcmp(line, "X") == 0) break;

        // Find the type character (last non-space character after space)
        // Format: "identifier type"
        char *space = strrchr(line, ' ');
        if (!space) break;
        char type = *(space + 1);
        *space = '\0';
        char *identifier = line;

        // Split identifier into words
        char words[100][100];
        int word_count = 0;

        if (strchr(identifier, '_')) {
            // underscore format
            char temp[1000];
            strcpy(temp, identifier);
            char *token = strtok(temp, "_");
            while (token) {
                // convert to lowercase
                for (int i = 0; token[i]; i++) token[i] = tolower(token[i]);
                strcpy(words[word_count++], token);
                token = strtok(NULL, "_");
            }
        } else {
            // CamelCase
            int start = 0;
            int id_len = strlen(identifier);
            for (int i = 1; i <= id_len; i++) {
                if (i == id_len || isupper(identifier[i])) {
                    int wlen = i - start;
                    strncpy(words[word_count], identifier + start, wlen);
                    words[word_count][wlen] = '\0';
                    // convert to lowercase
                    for (int j = 0; words[word_count][j]; j++)
                        words[word_count][j] = tolower(words[word_count][j]);
                    word_count++;
                    start = i;
                }
            }
        }

        // Output in desired format
        if (type == 'U') {
            for (int i = 0; i < word_count; i++) {
                words[i][0] = toupper(words[i][0]);
                printf("%s", words[i]);
            }
            printf("\n");
        } else if (type == 'L') {
            for (int i = 0; i < word_count; i++) {
                if (i == 0) words[i][0] = tolower(words[i][0]);
                else words[i][0] = toupper(words[i][0]);
                printf("%s", words[i]);
            }
            printf("\n");
        } else if (type == 'D') {
            for (int i = 0; i < word_count; i++) {
                if (i > 0) printf("_");
                printf("%s", words[i]);
            }
            printf("\n");
        }
    }
    return 0;
}

