import java.util.Scanner;

public class NamingConventionConverter {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        while (scanner.hasNext()) {
            String identifier = scanner.next();
            String type = scanner.next();

            if (identifier.equals("X") && type.equals("X")) {
                break;
            }

            String result = convertIdentifier(identifier, type.charAt(0));
            System.out.println(result);
        }

        scanner.close();
    }

    private static String convertIdentifier(String identifier, char targetType) {
        // First, determine the current format
        String[] words;

        if (identifier.contains("_")) {
            // Underscore format
            words = identifier.split("_");
        } else if (Character.isUpperCase(identifier.charAt(0))) {
            // Upper CamelCase
            words = splitCamelCase(identifier);
        } else {
            // Lower CamelCase
            words = splitCamelCase(identifier);
        }

        // Now convert to target format
        StringBuilder result = new StringBuilder();

        if (targetType == 'U') {
            // Upper CamelCase
            for (String word : words) {
                result.append(Character.toUpperCase(word.charAt(0)));
                result.append(word.substring(1).toLowerCase());
            }
        } else if (targetType == 'L') {
            // Lower CamelCase
            for (int i = 0; i < words.length; i++) {
                if (i == 0) {
                    result.append(words[i].toLowerCase());
                } else {
                    result.append(Character.toUpperCase(words[i].charAt(0)));
                    result.append(words[i].substring(1).toLowerCase());
                }
            }
        } else if (targetType == 'D') {
            // Underscore format
            for (int i = 0; i < words.length; i++) {
                if (i > 0) {
                    result.append("_");
                }
                result.append(words[i].toLowerCase());
            }
        }

        return result.toString();
    }

    private static String[] splitCamelCase(String camelCase) {
        StringBuilder wordBuilder = new StringBuilder();
        java.util.ArrayList<String> words = new java.util.ArrayList<>();

        for (int i = 0; i < camelCase.length(); i++) {
            char c = camelCase.charAt(i);

            if (Character.isUpperCase(c) && wordBuilder.length() > 0) {
                words.add(wordBuilder.toString());
                wordBuilder = new StringBuilder();
            }
            wordBuilder.append(c);
        }

        if (wordBuilder.length() > 0) {
            words.add(wordBuilder.toString());
        }

        return words.toArray(new String[0]);
    }
}

